@js:var awa = `{{source.key}}/discover.php`;
var response = java.ajax(awa);
var json = JSON.parse(response);
var categories = json.data || [];
var menu = [];

for (var i = 0; i < categories.length; i++) {
    var cat = categories[i];
    // 根据标题内容判断是否为标题
    var isHeader = (cat.title.indexOf("☆") !== -1) ||
                   (cat.title.indexOf("❀") !== -1) ||
                   (cat.title.indexOf("°・") !== -1) ||
                   (cat.title.indexOf("🔖") !== -1) ||
                   (cat.title.endsWith("❀❀❀"));
    if (isHeader) {
        menu.push({
            title: cat.title,
            url: "",
            style: {
                layout_flexGrow: 1,
                layout_flexBasisPercent: 1.0,
                textAlign: "center",
                fontWeight: "bold"
            }
        });
    } else {
        var listUrl = awa + "?source=" + encodeURIComponent(cat.source)
                    + "&path=" + encodeURIComponent(cat.path)
                    + "&page={{page}}";
        menu.push({
            title: cat.title,
            url: listUrl,
            style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.35 }
        });
    }
}
JSON.stringify(menu);

