@js:(function() {
    var data;
    try {
        data = typeof result === 'string' ? JSON.parse(result) : result;
    } catch(e) {
        java.log("解析JSON失败: " + e);
        return "";
    }

    // 1. 检测是否为音频类型（听书/音乐）
    if (data.type === 'audio' || data.type === 'music') {
        var audioUrl = data.data && (data.data.audio_url || data.data.music_url);
        if (audioUrl) {
            return audioUrl;
        } else {
            java.log("音频类型但未找到音频链接");
            return "";
        }
    }

    // 2. 原有逻辑：content 或 images
    if (data.content) {
        return data.content;
    }

    if (data.images && Array.isArray(data.images) && data.images.length) {
        return data.images.map(function(img) {
            var url = typeof img === 'string' ? img : img.url || img.src;
            return '<img src="' + url + '">';
        }).join('\n');
    }

    java.log("未找到content、images或音频链接");
    return "";
})();

